public static class YGPTApp {
 public const string Version=HostCore.Version;
 public static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=32*1024*1024};
 public static string Base=AppDomain.CurrentDomain.BaseDirectory;
 public static string DefaultData=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"YGPTLocal");
 public static string Q(string s){if(s.IndexOf('"')>=0||s.Any(c=>c<' '))throw new Exception("Invalid path characters");return "\""+s+new string('\\',s.Reverse().TakeWhile(c=>c=='\\').Count())+"\"";}
 public static string Arg(string[] a,string k,string fallback){int i=Array.IndexOf(a,k);return i>=0&&i+1<a.Length?a[i+1]:fallback;}
 [STAThread] public static void Main(string[] args){try{
  Thread.CurrentThread.CurrentUICulture=System.Globalization.CultureInfo.GetCultureInfo("en-US");Thread.CurrentThread.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("en-US");
  AppContext.SetSwitch("Switch.UseLegacyAccessibilityFeatures",false);AppContext.SetSwitch("Switch.UseLegacyAccessibilityFeatures.2",false);AppContext.SetSwitch("Switch.UseLegacyAccessibilityFeatures.3",false);
  string data=Arg(args,"--data-dir",DefaultData);
  if(args.Contains("--background")){Background(data);return;}
  if(args.Contains("--uninstall-worker")){RemoveInstall(Arg(args,"--install-dir",Base),data);return;}
  if(args.Contains("--self-test")){var b=Encoding.UTF8.GetBytes("YGPT fixture");if(!b.SequenceEqual(ProtectedData.Unprotect(ProtectedData.Protect(b,null,DataProtectionScope.CurrentUser),null,DataProtectionScope.CurrentUser)))Environment.Exit(2);return;}
  bool ownSetup;using(var setupOwner=new Mutex(true,"Local\\YGPT-setup-"+HostCore.OwnerId(data),out ownSetup)){if(!ownSetup)return;
  ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;
  var app=new Application();var w=new SetupWindow(data,Arg(args,"--install-dir",File.Exists(Path.Combine(Base,".ygpt-install.json"))?Base:Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","YGPTLocal")));
  if(args.Contains("--uninstall"))w.Loaded+=(s,e)=>w.Uninstall();app.Run(w);}
 }catch(Exception ex){MessageBox.Show(ex.Message,"YGPT Local",MessageBoxButton.OK,MessageBoxImage.Error);Environment.ExitCode=1;}}
 public static string Hash(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 public static string RandomKey(){var b=new byte[32];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return Convert.ToBase64String(b).TrimEnd('=').Replace('+','-').Replace('/','_');}
 public static Dictionary<string,object> Read(string p){return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(p));}
 public static void PrivateDirectory(string p){Directory.CreateDirectory(p);CheckPath(p);var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WindowsIdentity.GetCurrent().User,new SecurityIdentifier("S-1-5-18")})acl.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(p,acl);}
 public static void CheckPath(string p){string x=Path.GetFullPath(p);if(x.TrimEnd('\\')==Path.GetPathRoot(x).TrimEnd('\\'))throw new Exception("A drive root is not an application folder");for(string t=x;!String.IsNullOrEmpty(t);t=Path.GetDirectoryName(t)){if(Directory.Exists(t)&&(File.GetAttributes(t)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked installation/data paths are not supported");}}
 public static Dictionary<string,object> Secrets(string data){string p=Path.Combine(data,"credentials.dpapi");if(!File.Exists(p))return new Dictionary<string,object>();string s=File.ReadAllText(p);if(!s.StartsWith("dpapi:"))throw new Exception("Unencrypted credentials refused");return Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(s.Substring(6)),null,DataProtectionScope.CurrentUser)));}
 public static void SaveSecrets(string data,Dictionary<string,object> s){PrivateDirectory(data);string p=Path.Combine(data,"credentials.dpapi");if(File.Exists(p)){if(Json.Serialize(Secrets(data))==Json.Serialize(s))return;File.Copy(p,p+".before-"+DateTime.UtcNow.Ticks);}HostCore.SaveText(p,"dpapi:"+Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(Json.Serialize(s)),null,DataProtectionScope.CurrentUser)));}
 public static string Node(string install,string script,string arg,string input){var si=new ProcessStartInfo(Path.Combine(install,"runtimes","node","node.exe"),Q(Path.Combine(install,script))+" "+(String.IsNullOrEmpty(arg)?"":Q(arg))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=true,WorkingDirectory=install};si.EnvironmentVariables["PYTHONDONTWRITEBYTECODE"]="1";si.EnvironmentVariables["PATH"]=Path.Combine(install,"runtimes","node")+";"+si.EnvironmentVariables["PATH"];using(var p=Process.Start(si)){var err=p.StandardError.ReadToEndAsync();var read=p.StandardOutput.ReadToEndAsync();if(input!=null)p.StandardInput.Write(input);p.StandardInput.Close();if(!p.WaitForExit(180000)){p.Kill();throw new Exception("Setup timed out. Inspect configuration before retrying; external resource creation may need reconciliation.");}string output=read.Result.Trim();if(String.IsNullOrEmpty(output))throw new Exception("Local component failed. Check runtime files and Windows permissions.");return output;}}
 public static void StartBackground(string install,string data){HostCore.Start(install,data);}
 public static Dictionary<string,object> LocalRequest(string data,string route,bool post){var c=Read(Path.Combine(data,"ygpt.config.json"));var s=Secrets(data);var req=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+Convert.ToString(c["port"])+route);req.Timeout=15000;req.Headers["Authorization"]="Bearer "+s["localKey"];if(post){req.Method="POST";req.ContentLength=0;}using(var r=req.GetResponse())using(var reader=new StreamReader(r.GetResponseStream()))return Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());}
 public static bool IsOwnService(string data,int port){try{var c=Read(Path.Combine(data,"ygpt.config.json"));return Convert.ToInt32(c["port"])==port&&Convert.ToString(LocalRequest(data,"/healthz",false)["product"])=="YGPT Local";}catch{return false;}}
 public static void StopForMaintenance(string data){if(File.Exists(Path.Combine(data,"connection.json"))&&HostCore.S(HostCore.Read(Path.Combine(data,"connection.json")),"architecture").StartsWith("watchdog-")){HostCore.Pause(data);return;}if(!File.Exists(Path.Combine(data,"ygpt.config.json")))return;bool connected=false;try{LocalRequest(data,"/healthz",false);connected=true;}catch(WebException ex){if(ex.Status!=WebExceptionStatus.ConnectFailure)throw new Exception("Could not confirm the existing local service identity. Close active tasks and retry.");}
  DateTime requested=DateTime.UtcNow;if(connected){var r=LocalRequest(data,"/maintenance/drain",true);if(!(bool)r["safeToStop"])throw new Exception("Finish owned tasks and pending approvals before maintenance.");}File.WriteAllText(Path.Combine(data,"paused"),"owner maintenance");
  for(int i=0;i<150;i++){bool stopped=false;try{var p=Path.Combine(data,"service-health.json");stopped=File.Exists(p)&&File.GetLastWriteTimeUtc(p)>=requested&&Read(p).ContainsKey("stopped")&&(bool)Read(p)["stopped"];}catch{}if(stopped||!connected){Thread.Sleep(1200);return;}Thread.Sleep(200);}throw new Exception("The existing service has not stopped safely. No application files were replaced.");}
 public static void Background(string data){HostCore.Start(Base,data);}
 public static string ShortcutPath(string data){return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),"Programs","YGPT Local"+(String.Equals(Path.GetFullPath(data),Path.GetFullPath(DefaultData),StringComparison.OrdinalIgnoreCase)?"":" - "+HostCore.OwnerId(data).Substring(0,8))+".lnk");}
 public static void Shortcut(string install,string data){string p=ShortcutPath(data);object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));object link=shell.GetType().InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{p});var t=link.GetType();t.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{Path.Combine(install,"YGPTLocal.exe")});t.InvokeMember("Arguments",BindingFlags.SetProperty,null,link,new object[]{"--data-dir "+Q(data)});t.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}
 public static void Register(string install,string data,bool startup){string id=HostCore.OwnerId(data).Substring(0,12);using(var k=Registry.CurrentUser.CreateSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\YGPTLocal-"+id)){k.SetValue("DisplayName","YGPT Local");k.SetValue("DisplayVersion",Version);k.SetValue("DisplayIcon",Path.Combine(install,"YGPTLocal.exe"));k.SetValue("InstallLocation",install);k.SetValue("UninstallString",Q(Path.Combine(install,"YGPTLocal.exe"))+" --uninstall --data-dir "+Q(data));}HostCore.RegisterTask(install,data,startup);Shortcut(install,data);}
 public static void InstallPayload(string install){CheckPath(install);if(Directory.Exists(install)&&Directory.GetFileSystemEntries(install).Length>0&&!File.Exists(Path.Combine(install,".ygpt-install.json")))throw new Exception("Choose an empty directory. Unrelated applications will not be replaced.");if(File.Exists(Path.Combine(install,".ygpt-install.json"))){var old=Read(Path.Combine(install,".ygpt-install.json"));if((string)old["product"]!="YGPT Local"||!String.Equals(Path.GetFullPath((string)old["installRoot"]),Path.GetFullPath(install),StringComparison.OrdinalIgnoreCase))throw new Exception("Existing installation identity does not match");}
  using(var payload=Assembly.GetExecutingAssembly().GetManifestResourceStream("YGPT.Payload")){if(payload==null){if(!String.Equals(HostCore.Full(Assembly.GetExecutingAssembly().Location),Path.Combine(HostCore.Full(install),"YGPTLocal.exe"),StringComparison.OrdinalIgnoreCase)||!File.Exists(Path.Combine(install,".ygpt-install.json")))throw new Exception("Use the complete Setup package to install or upgrade. Installed Settings can reconfigure its own verified runtime.");var existing=Read(Path.Combine(install,"manifest.json"));foreach(object item in (System.Collections.IEnumerable)existing["files"]){var f=(Dictionary<string,object>)item;string file=Path.GetFullPath(Path.Combine(install,(string)f["path"]));HostCore.CheckPath(file);if(!HostCore.Within(file,install)||!File.Exists(file)||Hash(file)!=(string)f["sha256"])throw new Exception("Runtime integrity needs repair using the full Setup package.");}return;}string stage=install+".staging-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(stage);CheckPath(stage);long total=0;using(var zip=new ZipArchive(payload,ZipArchiveMode.Read)){foreach(var e in zip.Entries){if(e.FullName.EndsWith("/")||e.FullName.EndsWith("\\"))continue;string rel=e.FullName.Replace('/','\\');string target=Path.GetFullPath(Path.Combine(stage,rel));if(!target.StartsWith(Path.GetFullPath(stage)+"\\",StringComparison.OrdinalIgnoreCase)||rel.Contains(":")||(e.ExternalAttributes>>16&0xF000)==0xA000)throw new Exception("Unsafe archive entry");total+=e.Length;if(total>1024L*1024*1024)throw new Exception("Payload exceeds expected bounds");Directory.CreateDirectory(Path.GetDirectoryName(target));using(var input=e.Open())using(var output=new FileStream(target,FileMode.CreateNew))input.CopyTo(output);}}
   var manifest=Read(Path.Combine(stage,"manifest.json"));foreach(object record in (System.Collections.IEnumerable)manifest["files"]){var f=(Dictionary<string,object>)record;string rel=(string)f["path"],p=Path.GetFullPath(Path.Combine(stage,rel));if(!p.StartsWith(Path.GetFullPath(stage)+"\\",StringComparison.OrdinalIgnoreCase)||Hash(p)!=(string)f["sha256"])throw new Exception("Installation payload integrity failed");}
   string previous=null;if(Directory.Exists(install)){if(Directory.GetFileSystemEntries(install).Length>0){previous=install+".previous-"+DateTime.UtcNow.Ticks;Directory.Move(install,previous);}else Directory.Delete(install,false);}try{Directory.Move(stage,install);}catch{if(previous!=null&&!Directory.Exists(install))Directory.Move(previous,install);throw;}File.WriteAllText(Path.Combine(install,".ygpt-install.json"),Json.Serialize(new{product="YGPT Local",version=Version,installRoot=Path.GetFullPath(install)}));}}
 public static void RemoveInstall(string install,string data){StopForMaintenance(data);HostCore.RegisterTask(install,data,false);CheckPath(install);var marker=Read(Path.Combine(install,".ygpt-install.json"));if((string)marker["product"]!="YGPT Local"||!String.Equals(Path.GetFullPath((string)marker["installRoot"]),Path.GetFullPath(install),StringComparison.OrdinalIgnoreCase))throw new Exception("Installation identity mismatch; nothing removed");
  var m=Read(Path.Combine(install,"manifest.json"));foreach(object r in (System.Collections.IEnumerable)m["files"]){var entry=(Dictionary<string,object>)r;string p=Path.GetFullPath(Path.Combine(install,(string)entry["path"]));if(!p.StartsWith(Path.GetFullPath(install)+"\\",StringComparison.OrdinalIgnoreCase))throw new Exception("Unsafe uninstall entry");HostCore.CheckPath(p);if(File.Exists(p)&&Hash(p)==(string)entry["sha256"])File.Delete(p);}foreach(var name in new[]{"manifest.json",".ygpt-install.json"}){string p=Path.Combine(install,name);if(File.Exists(p))File.Delete(p);}using(var k=Registry.CurrentUser.CreateSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run")){string value=Convert.ToString(k.GetValue("YGPTLocal"));if(value.StartsWith(Q(Path.Combine(install,"YGPTLocal.exe")),StringComparison.OrdinalIgnoreCase)&&value.IndexOf(Q(data),StringComparison.OrdinalIgnoreCase)>=0)k.DeleteValue("YGPTLocal",false);}
  string registration="Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\YGPTLocal-"+HostCore.OwnerId(data).Substring(0,12);bool ownsRegistration=false;using(var k=Registry.CurrentUser.OpenSubKey(registration)){ownsRegistration=k!=null&&String.Equals(Convert.ToString(k.GetValue("InstallLocation")),install,StringComparison.OrdinalIgnoreCase);}if(ownsRegistration){Registry.CurrentUser.DeleteSubKeyTree(registration,false);string link=ShortcutPath(data);if(File.Exists(link)){object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));object shortcut=shell.GetType().InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{link});if(String.Equals(Convert.ToString(shortcut.GetType().InvokeMember("TargetPath",BindingFlags.GetProperty,null,shortcut,null)),Path.Combine(install,"YGPTLocal.exe"),StringComparison.OrdinalIgnoreCase))File.Delete(link);}}MessageBox.Show("Unmodified application files removed. Changed or unknown files, private settings, encrypted credentials and snapshots were retained. Data folder:\n"+data,"YGPT Local");}
